<template><div class="page"><div class="section-title"><div><div class="eyebrow">INCIDENT INVESTIGATION</div><h2>故障排查</h2><span class="muted">{{incident?.alert_name}} · {{incident?.status}}</span></div><n-button @click="resolve">标记已解决</n-button></div><div class="panel"><n-descriptions bordered :column="2"><n-descriptions-item label="告警">{{incident?.alert_name}}</n-descriptions-item><n-descriptions-item label="Fingerprint">{{incident?.alert_fingerprint}}</n-descriptions-item><n-descriptions-item label="上下文" :span="2"><pre>{{JSON.stringify(incident?.context||{},null,2)}}</pre></n-descriptions-item></n-descriptions></div><div class="panel" v-if="actions.length"><div class="section-title"><h3>待确认修复动作</h3><span class="muted">Agent 只提出方案，执行前必须确认</span></div><n-list><n-list-item v-for="a in actions" :key="a.id"><div><strong>{{a.action_type}}</strong><div class="muted">目标：{{a.namespace}}/{{a.target}} · {{a.reason}}</div><div class="muted">风险：{{a.risk||'请确认影响范围'}}　回滚：{{a.rollback||'按维护文档执行'}}</div></div><template #suffix><n-space v-if="a.status==='pending_confirmation'"><n-button type="primary" size="small" @click="confirmAction(a.id)">确认执行</n-button><n-button size="small" @click="rejectAction(a.id)">拒绝</n-button></n-space><n-tag v-else>{{a.status}}</n-tag></template></n-list-item></n-list></div><section class="panel chat-main" style="height:55vh"><div class="messages"><div v-for="(m,i) in messages" :key="i" :class="['message',m.role]">{{m.content}}</div></div><div class="chat-input"><n-input v-model:value="input" placeholder="描述现象或询问 Agent 下一步排查..." @keydown.enter.exact.prevent="send"/><n-button type="primary" :loading="streaming" @click="send">发送</n-button></div></section></div></template>
<script setup>import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{useNotification}from'naive-ui';import{incidentApi,request,streamConversation}from'@/api';const route=useRoute(),notification=useNotification(),incident=ref(null),actions=ref([]),messages=ref([]),input=ref(''),streaming=ref(false);async function load(){incident.value=await incidentApi.get(route.params.id);const[m,a]=await Promise.all([request.get(`/incidents/${route.params.id}/messages`),incidentApi.actions(route.params.id)]);messages.value=(m.messages||[]).map(x=>({role:x.role,content:x.content}));actions.value=a.actions||[]}async function send(){const q=input.value.trim();if(!q||streaming.value)return;input.value='';messages.value.push({role:'user',content:q},{role:'assistant',content:''});streaming.value=true;try{await streamConversation(`/incidents/${route.params.id}/chatStream`,q,t=>messages.value.at(-1).content+=t)}catch(error){const reply=messages.value.at(-1);reply.content=reply.content?`${reply.content}\n\n[请求中断] ${error.message}`:`请求失败：${error.message}`;notification.error({title:'Incident Agent 请求失败',content:error.message,duration:8000})}finally{streaming.value=false}}async function confirmAction(id){await incidentApi.confirm(route.params.id,id);await load()}async function rejectAction(id){await incidentApi.reject(route.params.id,id);await load()}async function resolve(){await request.post(`/incidents/${route.params.id}/resolve`);await load()}onMounted(load)</script>
